using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Nodes;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.Extensions.DependencyInjection;
using Shop.Modules.Credit;
using Shop.Modules.Sales;
using Shop.Modules.Inventory;
using Shop.SharedKernel;
using Xunit;
using IdentityContext=Shop.Modules.Identity.IdentityDbContext;
namespace Shop.SqlTests;
public sealed class ChequeApprovalSqlTests():CreditRequirementsSqlBase(new SqlFixture()),IAsyncLifetime
{
    private WebApplicationFactory<Program>? auth;private Task<HttpClient> Staff(string role)=>base.Staff(role,auth??=sql.Factory.WithWebHostBuilder(_=>{}));public Task InitializeAsync()=>sql.InitializeAsync();public async Task DisposeAsync(){auth?.Dispose();await sql.DisposeAsync();}
    private sealed record Scenario(HttpClient Customer,string Owner,JsonNode Order,JsonNode Schedule,string Variant);
    private static string V(JsonNode n,string k)=>CreditCheckoutQuoteQa.Text(n,k);
    private static string OrderId(Scenario s)=>V(s.Order["summary"]!,"id");private static string Base(Scenario s)=>"/api/admin/credit/orders/"+s.Owner+"/"+OrderId(s)+"/cheque-approvals";private static string Own(Scenario s)=>"/api/credit/orders/"+OrderId(s)+"/cheque-approvals";private static string Ledger(Scenario s)=>Base(s).Replace("/cheque-approvals","/cheques");
    private static async Task<JsonNode> Read(HttpResponseMessage response){using(response){var raw=await response.Content.ReadAsStringAsync();Assert.True(response.IsSuccessStatusCode,$"HTTP{(int)response.StatusCode}: {raw}");Assert.Contains("no-store",response.Headers.CacheControl!.ToString());Assert.Contains("noindex",response.Headers.GetValues("X-Robots-Tag").Single());if(Environment.GetEnvironmentVariable("SHOP_CHEQUE_APPROVAL_WIRE_DIR")is{Length:>0}dir&&response.RequestMessage!.RequestUri!.AbsolutePath.Contains("/cheque-approvals",StringComparison.Ordinal)){Directory.CreateDirectory(dir);var id=Id();await File.WriteAllTextAsync(Path.Combine(dir,id+".json"),raw);await File.WriteAllTextAsync(Path.Combine(dir,id+".meta.json"),JsonSerializer.Serialize(new{actualSqlHttpResponse=true,syntheticQaOnly=true,status=(int)response.StatusCode,method=response.RequestMessage.Method.Method,path=response.RequestMessage.RequestUri.PathAndQuery}));}return JsonNode.Parse(raw)!;}}
    private async Task<Scenario> Ready(HttpClient finance,HttpClient reviewer)
    {
        using var helper=new CreditOrderSqlTests(sql);var s=await helper.Ready(finance,reviewer);var input=new CreditOrderInput(V(s.Quote,"id"),V(s.Quote,"fingerprint"),"Synthetic cheque custody QA","09100000000",new("IR","تهران","تهران","Synthetic QA only; no physical delivery","1234567890"),"No real person, bank instrument or funds",true,true);
        var created=await CreditOrderQa.Read(await s.Customer.PostAsJsonAsync("/api/credit-orders/commands/"+Id(),input));var order=created["order"]!;var orderId=V(order["summary"]!,"id");var path="/api/admin/credit/orders/"+s.Owner+"/"+orderId+"/schedule";var anchor=DateOnly.FromDateTime(TimeZoneInfo.ConvertTime(DateTimeOffset.UtcNow,TimeZoneInfo.FindSystemTimeZoneById("Asia/Tehran")).DateTime).ToString("yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture);var previewInput=new CreditSchedulePreviewInput(V(order["summary"]!,"version"),null,"Persian",anchor);var preview=await CreditScheduleQa.Read(await finance.PostAsJsonAsync(path+"/preview",previewInput));var schedule=await CreditScheduleQa.Read(await finance.PostAsJsonAsync(path+"/commands/"+Id(),new SaveCreditScheduleInput(previewInput.OrderVersion,null,"Persian",anchor,V(preview,"fingerprint"),true)));return new(s.Customer,s.Owner,order,schedule["revision"]!,s.Goods.Variant);
    }
    private static string Cheque(JsonNode r)=>V(r["cheque"]!,"id");
    private static async Task<JsonNode> Receive(HttpClient f,Scenario s,int sequence=1)=>await CreditScheduleQa.Read(await f.PostAsJsonAsync(Ledger(s)+"/receive/commands/"+Id(),new ReceiveChequeInput(V(s.Order["summary"]!,"version"),V(s.Schedule,"version"),sequence,"SYNTHETIC-CHEQUE-APPROVAL-ONLY","Synthetic private instrument",DateTimeOffset.UtcNow,true)));
    private static ChequeApprovalInput Input(Scenario s,JsonNode cheque,string action="Approve",string? version=null,bool closed=false)=>new(action,V(s.Order["summary"]!,"version"),V(s.Schedule,"version"),V(cheque["cheque"]!,"version"),version,"Synthetic private approval 🎮",DateTimeOffset.UtcNow,true,closed);
    private static string Version(JsonNode r)=>V(r["event"]!["summary"]!,"version");
    private static async Task<JsonNode> Write(HttpClient f,Scenario s,JsonNode cheque,ChequeApprovalInput input,string? cmd=null)=>await Read(await f.PostAsJsonAsync(Base(s)+"/"+Cheque(cheque)+"/commands/"+(cmd??Id()),input));
    private static async Task<JsonNode> Move(HttpClient f,Scenario s,JsonNode cheque,string action)=>await CreditScheduleQa.Read(await f.PostAsJsonAsync(Ledger(s)+"/"+Cheque(cheque)+"/commands/"+Id(),new MoveChequeInput(V(cheque["cheque"]!,"version"),action,"Synthetic ledger transition",DateTimeOffset.UtcNow,true,false)));
    [Fact]public async Task EachCurrentInstrumentMustBeExplicitlyApprovedAndCustomerNeverSeesPrivateNotes()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var empty=await Read(await customer.GetAsync(Own(s)));Assert.False(empty["allChequesApproved"]!.GetValue<bool>());Assert.All(empty["items"]!.AsArray(),x=>Assert.Null(x!["cheque"]));
        for(int i=1;i<=s.Schedule["calculation"]!["lines"]!.AsArray().Count;i++){var cheque=await Receive(f,s,i);var approved=await Write(f,s,cheque,Input(s,cheque));Assert.Equal("Approved",V(approved["event"]!["summary"]!,"state"));Assert.False(approved["canPay"]!.GetValue<bool>());Assert.False(approved["canFulfill"]!.GetValue<bool>());Assert.False(approved["bankVerified"]!.GetValue<bool>());}
        var own=await Read(await customer.GetAsync(Own(s)));Assert.True(own["allChequesApproved"]!.GetValue<bool>());foreach(var secret in new[]{"SYNTHETIC-CHEQUE-APPROVAL-ONLY","Synthetic private approval","note","actorId","instrumentReference"})Assert.DoesNotContain(secret,own.ToJsonString(),StringComparison.OrdinalIgnoreCase);
        await using var scope=sql.Factory.Services.CreateAsyncScope();Assert.Equal(OrderState.AwaitingPayment,(await scope.ServiceProvider.GetRequiredService<SalesDbContext>().Orders.SingleAsync(x=>x.Id==OrderId(s))).State);Assert.Equal(1,(await scope.ServiceProvider.GetRequiredService<InventoryDbContext>().Stock.SingleAsync(x=>x.VariantId==s.Variant)).Reserved);Assert.Equal(s.Schedule["calculation"]!["lines"]!.AsArray().Count,await scope.ServiceProvider.GetRequiredService<CreditDbContext>().ChequeApprovalCommands.CountAsync());
    }
    [Fact]public async Task EveryLedgerChangeInvalidatesOldApprovalAndUnsafeCustodyCannotBeApproved()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var cheque=await Receive(f,s);var first=await Write(f,s,cheque,Input(s,cheque));cheque=await Move(f,s,cheque,"Deposit");var page=await Read(await f.GetAsync(Base(s)));Assert.False(page["items"]![0]!["approvedForCurrentCheque"]!.GetValue<bool>());using(var stale=await f.PostAsJsonAsync(Base(s)+"/"+Cheque(cheque)+"/commands/"+Id(),Input(s,cheque)))Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);var second=await Write(f,s,cheque,Input(s,cheque,version:Version(first)));cheque=await Move(f,s,cheque,"ReportBounce");using(var bounced=await f.PostAsJsonAsync(Base(s)+"/"+Cheque(cheque)+"/commands/"+Id(),Input(s,cheque,version:Version(second))))Assert.Equal(HttpStatusCode.Conflict,bounced.StatusCode);var revoked=await Write(f,s,cheque,Input(s,cheque,"Revoke",Version(second)));cheque=await Move(f,s,cheque,"Deposit");var third=await Write(f,s,cheque,Input(s,cheque,version:Version(revoked)));Assert.Equal(4,third["event"]!["summary"]!["sequence"]!.GetValue<int>());var history=await Read(await f.GetAsync(Base(s)+"/"+Cheque(cheque)+"/history"));Assert.Equal(4,history["items"]!.AsArray().Count);
    }
    [Fact]public async Task AuditRollbackSameUuidReplayAndCompetingRevocationsAreAtomic()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var cheque=await Receive(f,s);var cmd=Id();var input=Input(s,cheque);var path=Base(s)+"/"+Cheque(cheque)+"/commands/"+cmd;
        await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_QA_ApprovalAudit CHECK ([Action]<>'CREDIT_CHEQUE_APPROVAL_APPROVE')");try{using var failed=await f.PostAsJsonAsync(path,input);Assert.Equal(HttpStatusCode.Conflict,failed.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_QA_ApprovalAudit");}
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();Assert.False(await db.ChequeApprovals.AnyAsync());Assert.False(await db.ChequeApprovalEvents.AnyAsync());Assert.False(await db.ChequeApprovalCommands.AnyAsync());}
        var both=await Task.WhenAll((await Task.WhenAll(f.PostAsJsonAsync(path,input),f.PostAsJsonAsync(path,input))).Select(Read));Assert.Single(both,x=>x["replayed"]!.GetValue<bool>());var revoke=Input(s,cheque,"Revoke",Version(both[0]));var race=await Task.WhenAll(f.PostAsJsonAsync(Base(s)+"/"+Cheque(cheque)+"/commands/"+Id(),revoke),f.PostAsJsonAsync(Base(s)+"/"+Cheque(cheque)+"/commands/"+Id(),revoke));Assert.Single(race,x=>x.StatusCode==HttpStatusCode.OK);Assert.Single(race,x=>x.StatusCode==HttpStatusCode.Conflict);foreach(var r in race)if(r.IsSuccessStatusCode)await Read(r);else r.Dispose();using(var conflict=await f.PostAsJsonAsync(path,input with{Note="Different intent"}))Assert.Equal(HttpStatusCode.Conflict,conflict.StatusCode);var receipt=await Read(await f.GetAsync(path));Assert.True(receipt["replayed"]!.GetValue<bool>());await using var final=sql.Factory.Services.CreateAsyncScope();Assert.Equal(1,await final.ServiceProvider.GetRequiredService<IdentityContext>().Audit.CountAsync(x=>x.Resource==path));
    }
    [Fact]public async Task ClosedCorrectionAndCancellationRaceDoNotReviveStockOrScopeUse()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var cheque=await Receive(f,s);var first=await Write(f,s,cheque,Input(s,cheque));await CreditOrderQa.Read(await customer.PostAsJsonAsync("/api/orders/v2/"+OrderId(s)+"/cancel",new{version=V(s.Order["summary"]!,"version")}));var page=await Read(await f.GetAsync(Base(s)));s.Order["summary"]!["version"]=V(page,"orderVersion");using(var noAck=await f.PostAsJsonAsync(Base(s)+"/"+Cheque(cheque)+"/commands/"+Id(),Input(s,cheque,"Revoke",Version(first))))Assert.Equal(HttpStatusCode.Conflict,noAck.StatusCode);var revoked=await Write(f,s,cheque,Input(s,cheque,"Revoke",Version(first),true));using(var revive=await f.PostAsJsonAsync(Base(s)+"/"+Cheque(cheque)+"/commands/"+Id(),Input(s,cheque,version:Version(revoked))))Assert.Equal(HttpStatusCode.Conflict,revive.StatusCode);
        var other=await Ready(f,reviewer);using var otherCustomer=other.Customer;var otherCheque=await Receive(f,other);var both=await Task.WhenAll(otherCustomer.PostAsJsonAsync("/api/orders/v2/"+OrderId(other)+"/cancel",new{version=V(other.Order["summary"]!,"version")}),f.PostAsJsonAsync(Base(other)+"/"+Cheque(otherCheque)+"/commands/"+Id(),Input(other,otherCheque)));Assert.Equal(HttpStatusCode.OK,both[0].StatusCode);Assert.Contains(both[1].StatusCode,new[]{HttpStatusCode.OK,HttpStatusCode.Conflict});foreach(var r in both)r.Dispose();await using var scope=sql.Factory.Services.CreateAsyncScope();Assert.Equal(0,(await scope.ServiceProvider.GetRequiredService<InventoryDbContext>().Stock.SingleAsync(x=>x.VariantId==other.Variant)).Reserved);Assert.True(await scope.ServiceProvider.GetRequiredService<CreditDbContext>().PurchaseScopeUses.AnyAsync(x=>x.OrderId==OrderId(other)));
    }
    [Fact]public async Task AuthorizationUnknownFieldsTamperingImmutableForeignKeysAndDownFailClosed()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");using var sales=await Staff("SalesManager");var s=await Ready(f,reviewer);using var customer=s.Customer;var cheque=await Receive(f,s);foreach(var denied in new[]{reviewer,sales,customer}){using var r=await denied.GetAsync(Base(s));Assert.Equal(HttpStatusCode.Forbidden,r.StatusCode);}var other=await Customer();using(var stranger=other.Client){using var r=await stranger.GetAsync(Own(s));Assert.Equal(HttpStatusCode.NotFound,r.StatusCode);}var forged=JsonSerializer.SerializeToNode(Input(s,cheque),new JsonSerializerOptions(JsonSerializerDefaults.Web))!.AsObject();forged["amountRial"]="1";using(var bad=await f.PostAsJsonAsync(Base(s)+"/"+Cheque(cheque)+"/commands/"+Id(),forged))Assert.Equal(HttpStatusCode.BadRequest,bad.StatusCode);using(var query=await f.GetAsync(Base(s)+"/"+Cheque(cheque)+"/history?beforeSequence=01"))Assert.Equal(HttpStatusCode.BadRequest,query.StatusCode);
        var first=await Write(f,s,cheque,Input(s,cheque));await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var head=await db.ChequeApprovals.SingleAsync();head.OwnerId="wrong_owner";Assert.Equal("cheque_approval_history_immutable",(await Assert.ThrowsAsync<BusinessException>(()=>db.SaveChangesAsync())).Code);db.ChangeTracker.Clear();var id=V(first["event"]!["summary"]!,"id");await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[ChequeApprovalEvents] SET [ChequeId]={Id()} WHERE [Id]={id}"));await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.GetService<IMigrator>().MigrateAsync("20261027202932_CreditUpfront"));await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[ChequeApprovalEvents] SET [ProtectedEvent]={new byte[]{1,2,3}} WHERE [Id]={id}");}using(var corrupt=await f.GetAsync(Base(s)))Assert.Equal(HttpStatusCode.ServiceUnavailable,corrupt.StatusCode);
    }
    private sealed class FutureClock(DateTimeOffset at):TimeProvider{public override DateTimeOffset GetUtcNow()=>at;}
    [Fact]public async Task ExpiryAndLedgerRacesKeepOldReceiptRecoverableWithoutFreshAuthority()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var cheque=await Receive(f,s);var cmd=Id();var input=Input(s,cheque);var first=await Write(f,s,cheque,input,cmd);using var future=sql.Factory.WithWebHostBuilder(b=>b.ConfigureTestServices(services=>services.AddSingleton<TimeProvider>(new FutureClock(DateTimeOffset.Parse(V(s.Order["summary"]!,"expiresAt")).AddHours(1)))));using var later=future.CreateClient(new(){HandleCookies=false});foreach(var h in f.DefaultRequestHeaders)later.DefaultRequestHeaders.TryAddWithoutValidation(h.Key,h.Value);var path=Base(s)+"/"+Cheque(cheque)+"/commands/"+cmd;var replay=await Read(await later.PostAsJsonAsync(path,input));Assert.True(replay["replayed"]!.GetValue<bool>());using(var expired=await later.PostAsJsonAsync(Base(s)+"/"+Cheque(cheque)+"/commands/"+Id(),input))Assert.Equal(HttpStatusCode.Conflict,expired.StatusCode);
        var other=await Ready(f,reviewer);using var otherCustomer=other.Customer;var c=await Receive(f,other);var race=await Task.WhenAll(f.PostAsJsonAsync(Base(other)+"/"+Cheque(c)+"/commands/"+Id(),Input(other,c)),f.PostAsJsonAsync(Ledger(other)+"/"+Cheque(c)+"/commands/"+Id(),new MoveChequeInput(V(c["cheque"]!,"version"),"Deposit","Synthetic competing custody",DateTimeOffset.UtcNow,true,false)));Assert.Equal(HttpStatusCode.OK,race[1].StatusCode);Assert.Contains(race[0].StatusCode,new[]{HttpStatusCode.OK,HttpStatusCode.Conflict});foreach(var r in race)r.Dispose();var page=await Read(await f.GetAsync(Base(other)));Assert.False(page["items"]![0]!["approvedForCurrentCheque"]!.GetValue<bool>());
    }
}
